mapper.update:
UPDATE biz_flowchart_draft
SET schema_version = #{draft.schemaVersion},
    document_json = #{draft.documentJson},
    revision = revision + 1,
    update_time = NOW()
WHERE student_id = #{draft.studentId}
  AND lesson_id = #{draft.lessonId}
  AND question_id = #{draft.questionId}
  AND revision = #{expectedRevision}

mapper.select:
SELECT COALESCE(MAX(version_no), 0) + 1
FROM biz_flowchart_submission
WHERE student_id = #{studentId} AND lesson_id = #{lessonId} AND question_id = #{questionId}
